  str_season_maze_s2_help_title_604 = "Orbe de sueño",
  str_season_maze_s2_help_title_605 = "Artículo de Ayuda de Sueño",
  str_season_maze_s2_help_title_701 = "Tipo de Orbe de Sueño",
  str_season_maze_s2_help_title_702 = "Energía del Orbe de Sueño",
  str_season_maze_s2_help_title_703 = "Nivel de Orbe de Sueño",
  str_season_maze_s2_help_title_704 = "Síntesis de Orbe de Sueño",
  str_season_maze_s2_help_title_705 = "Transmisión del Orbe de Sueño",
  str_season_maze_s2_help_disc_101 = "Los elementos inestables de los sueños pasados aún persisten en el reino de los sueños, listos para golpear la realidad en cualquier momento. Con la ayuda del Enlightener, los Navegantes ahora pueden aventurarse de nuevo en los sueños para participar en diversos eventos de exploración, mejorando su destreza dentro de los sueños. Al derrotar al Devorador de Sueños Definitivo, existe la posibilidad de restaurar la estabilidad a la energía de los sueños.",
  str_season_maze_s2_help_disc_102 = "Los navegantes liderarán el Enlightener, aprovechando el poder de la Carta de Adivinación de Sueños, para atravesar diversos reinos de sueños y desencadenar eventos dentro de ellos. A lo largo de la exploración, los navegantes pueden invocar a los Aurorianos y recolectar Equipo de Sueños, Orbes de Sueños y otros recursos de sueños para mejorar sus habilidades. Después de derrotar finalmente al Devorador de Sueños y al Devorador de Sueños Definitivo, el Ensueño se completará, otorgando ricas recompensas.",
  str_season_maze_s2_help_disc_201 = "El Enlightener evaluará el rendimiento de los Navegantes en los sueños y registrará sus puntuaciones. Acumula suficientes puntuaciones para obtener las recompensas correspondientes.",
  str_season_maze_s2_help_disc_202 = "Después de cada exploración, el Enlightener registrará la puntuación correspondiente basada en el Nivel de Sueño y el Progreso de la Exploración. Acumula suficientes puntuaciones para alcanzar ciertos hitos y obtener las recompensas correspondientes. Además, puedes obtener puntuaciones extra completando las Misiones de Sueño.",
  str_season_maze_s2_help_disc_203 = "Cuando tus puntuaciones acumuladas alcancen ciertos hitos, puedes reclamar las recompensas correspondientes. Más hitos de recompensas se desbloquearán a intervalos regulares.",
  str_season_maze_s2_help_disc_204 = "Dentro de los sueños, hay varias Misiones de Sueño que emprender, las cuales otorgan puntuaciones adicionales al completarlas.",
  str_season_maze_s2_help_disc_301 = "Los sueños están estructurados en varios niveles. Cuanto más alto sea el nivel, más difícil será el desafío y más puntuaciones se ganarán al completarlo. Dentro de la pantalla de Nivel de Sueño, puedes ver el Devorador de Sueños Definitivo activo en cada nivel para diseñar tu estrategia de exploración en consecuencia.",
  str_season_maze_s2_help_disc_302 = "Comenzarás en el Nivel de Sueño 1 y desbloquearás el siguiente nivel al completar el actual, y algunos niveles se abrirán con el tiempo. La función Dream Orb estará disponible cuando se desbloquee el Nivel de Sueño 3, proporcionando soporte para tu exploración.",
  str_season_maze_s2_help_disc_303 = "Al entrar en un sueño, necesitas seleccionar 4 Aurorians para formar la alineación inicial para la exploración. Los Aurorians desplegados heredarán sus Niveles de Avance desde fuera de los sueños, pero no heredarán otras estadísticas cultivadas o niveles.",
  str_season_maze_s2_help_disc_304 = "Ciertos Aurorians no se pueden usar en Ecos de un Sueño, ni se pueden invocar durante las exploraciones; esta lista de Aurorians cambia con cada instancia de Ecos de un Sueño.",
  str_season_maze_s2_help_disc_401 = "Durante la exploración, los Navegantes pueden controlarse a sí mismos y llevar el Enlightener al viaje.",
  str_season_maze_s2_help_disc_402 = "El Enlightener divide un sueño en diferentes Reinos de Sueños basados en las fluctuaciones de la energía del sueño. Los Navegantes solo pueden atravesar entre los Reinos de Sueños, cada uno desencadenando diferentes eventos.",
  str_season_maze_s2_help_disc_403 = "Los navegantes pueden usar el poder de las Cartas de Adivinación de Sueños para moverse entre diferentes Reinos de Sueños. Los Pasos de Acción en las Cartas de Adivinación de Sueños determinan el número de Reinos de Sueños entre los que los navegantes pueden moverse, con algunas cartas también ofreciendo recursos adicionales o efectos especiales. Al comienzo de cada ronda, el Enlightener sacará un cierto número de Cartas de Adivinación de Sueños del mazo de cartas, y los Navegadores pueden seleccionar una para jugarla o arrastrarla directamente a la pantalla para ejecutar su efecto.",
  str_season_maze_s2_help_disc_404 = "Los navegantes pueden recolectar diversos recursos dentro de los sueños. Las Monedas de Sueño pueden comprar varios artículos, la EXP de Sueño mejora el Nivel de Sueño, el Interés de Sueño aumenta la cantidad de Monedas de Sueño obtenidas por ronda, y Cyclique garantiza la seguridad y estabilidad de la navegación dentro de los sueños.",
  str_season_maze_s2_help_disc_405 = "En la Bolsa de Herramientas, puedes ver los Aurorians desplegados en esta exploración, el Dream Gear adquirido y las Cartas de Divinación de Sueños añadidas al mazo.",
  str_season_maze_s2_help_disc_406 = "Los recuerdos y emociones dejados por los soñadores originales están envueltos capa por capa en energía de sueño, formando Orbes de Sueño. Los navegantes pueden ver los Orbes de Sueño obtenidos en esta exploración aquí y equiparlos o sintetizarlos.",
  str_season_maze_s2_help_disc_407 = "Los Devoradores de Sueños atacarán a los Navegantes después de un número establecido de rondas. Solo al derrotar a los Devoradores de Sueños, los Navegantes pueden continuar su exploración de sueños. El Devorador de Sueños Definitivo es el encuentro final. Derrotarlo para completar esta exploración, obteniendo puntuaciones basadas en el nivel de sueño y el progreso de la exploración.",
  str_season_maze_s2_help_disc_408 = "Aquí, los navegantes pueden ver las condiciones del campo de batalla y la información del enemigo de esta batalla, lo que les permite afinar sus tácticas. Los navegantes pueden obtener recompensas correspondientes al completar el desafío, pero en caso de fracaso, necesitan consumir Resonancia para otro intento.",
  str_season_maze_s2_help_disc_409 = "La EXP de Sueño obtenida durante las exploraciones puede elevar el Nivel de Sueño de los Navegantes, aumentando los niveles de los Aurorians y el equipo y desbloqueando nuevas Cartas de Divinación de Sueños y Artículos de Ayuda de Sueños para fortalecer los Ensueños.",
  str_season_maze_s2_help_disc_501 = "Los navegantes pueden entrar a los Peligrosos Reinos de Sueños para luchar contra enemigos y obtener la oportunidad de elegir un Equipo de Sueño al lograr la victoria.",
  str_season_maze_s2_help_disc_502 = "Cuando los Navegantes ingresan a los Reinos de Sueños Desconocidos, se activarán eventos aleatorios. Algunos eventos requieren sacar 3 Cartas de Adivinación de Sueños y determinar la suma de puntos. El éxito en la determinación otorga recompensas correspondientes.",
  str_season_maze_s2_help_disc_503 = "Al ingresar a los Reinos de Sueño de Recursos, los Navegantes pueden obtener varios tipos de recompensas de recursos, incluyendo Monedas de Sueño, EXP de Sueño y Orbes de Sueño. Cuantos más pasos se den antes de entrar a este Reino de Sueño, más ricas serán las recompensas.",
  str_season_maze_s2_help_disc_504 = "Al ingresar a los Reinos de Sueños Inexplorados, los Navegantes pueden desplegar Aurorianos para realizar misiones para ganancias continuas. Durante el despliegue, los Aurorianos no pueden participar en batallas y volverán automáticamente después de 5 rondas.",
  str_season_maze_s2_help_disc_505 = "Al ingresar a los Reinos del Sueño del Tesoro, los navegantes pueden elegir una recompensa de varias opciones para obtener.",
  str_season_maze_s2_help_disc_506 = "Al entrar en el Túnel del Reino de los Sueños, los Navegantes retrasan el asalto del Devorador de Sueños en 1 ronda.",
  str_season_maze_s2_help_disc_507 = "Ingresar al Reino del Sueño en Blanco no desencadenará ningún efecto.",
  str_season_maze_s2_help_disc_508 = "En el Reino de los Sueños de Adivinación, los Navegantes pueden gastar Monedas de Sueño para restablecer o eliminar las existentes Cartas de Adivinación de Sueños.",
  str_season_maze_s2_help_disc_509 = "En los Reinos de Sueño de Comercio, los Navegantes pueden intercambiar varios tipos de Orbes de Sueño entre sí.",
  str_season_maze_s2_help_disc_510 = "El Reino del Sueño Seguro es donde los Navegantes se recuperan, permitiéndoles convocar a los Aurorianos, comprar artículos, comprar medicinas o resucitar a los Aurorianos para mejorar su fuerza. Además, infundir Monedas de Sueño en la Forja de Sueños puede desbloquear artículos más poderosos para desafíos futuros.",
  str_season_maze_s2_help_disc_511 = "En la Teletransportación del Reino de los Sueños, serás teletransportado directamente a sus correspondientes Reinos de los Sueños sin pasar por otros sueños. Por favor, ten en cuenta que la teletransportación es solo de un solo sentido.",
  str_season_maze_s2_help_disc_512 = "En Dream Realm Gathering, puedes comprar Dream Gear.",
  str_season_maze_s2_help_disc_513 = "En la Invocación del Reino de los Sueños, puedes elegir un elemento e invocar a un Aurorian del elemento correspondiente en la dirección objetivo. Una vez elegido, el elemento no puede ser cambiado para una invocación dada.",
  str_season_maze_s2_help_disc_601 = "Los Navegadores pueden convocar a los Aurorians para que se unan a su alineación. Los Aurorians desplegados heredarán sus Niveles de Avance de los sueños externos, pero no heredarán otras estadísticas cultivadas o niveles. Aumenta tu Nivel de Sueño para elevar el nivel de los Aurorians y su equipo en los sueños.",
  str_season_maze_s2_help_disc_602 = "El Dream Gear es el precioso conocimiento y las valiosas reliquias dejadas por los Dream Wayfarers lo suficientemente valientes para explorar sueños en el río del tiempo. Puede desencadenar varios efectos para ayudar a los navegadores en sus Daydreams.",
  str_season_maze_s2_help_disc_603 = "Los navegantes pueden usar el poder de las Cartas de Adivinación de Sueños para moverse entre diferentes Reinos de Sueños. Los Pasos de Acción en las Cartas de Adivinación de Sueños determinan el número de Reinos de Sueños entre los que los navegantes pueden moverse, con algunas cartas que también ofrecen recursos adicionales o efectos especiales, incluyendo pero no limitado a Monedas de Sueño, Interés de Sueño, EXP de Sueño, Cyclique, etc.",
  str_season_maze_s2_help_disc_604 = "Los recuerdos y emociones dejados por los soñadores originales están envueltos capa por capa en energía de sueño, formando Orbes de Sueño. Los Orbes de Sueño pueden mejorar el poder de combate de los Navegantes en un sueño, ¡así que ten cuidado de no dejar que el Devorador de Sueños los recoja!",
  str_season_maze_s2_help_disc_605 = "Cuando se introducen en los sueños, los objetos del mundo real a veces son desgastados por la energía del sueño, formando los Artículos de Ayuda de Sueño. Cada Artículo de Ayuda de Sueño presenta efectos de asistencia únicos. Úsalos sabiamente para obtener apoyo en tus exploraciones.",
  str_season_maze_s2_help_disc_701 = "Existen 3 tipos de Orbes de Sueño: Orbes de Habilidad, Orbes de Mejora y Orbes de Carga. Los Orbes de Habilidad se utilizan para lanzar habilidades en batalla, los Orbes de Mejora potencian otros Orbes de Sueño equipados, y los Orbes de Carga otorgan ganancias de Energía más rápidas en batalla.",
  str_season_maze_s2_help_disc_702 = "En la batalla, ganas 1 punto de Energía del Orbe de Sueño por cada ficha que tus Aurorianos mueven y conectan. Después de conectar las fichas, si tienes más Energía que el requisito de Energía de tus Orbes de Sueño, las habilidades de tus Orbes de Sueño equipados se lanzarán en orden de izquierda a derecha.",
  str_season_maze_s2_help_disc_703 = "Las Esferas de Sueño vienen en 4 niveles y se pueden mejorar hasta las Esferas de Sueño de 3 estrellas. Cuanto mayor sea el nivel de una Esfera de Sueño, más fuertes serán sus efectos.",
  str_season_maze_s2_help_disc_704 = "Dos Orbes de Sueño del mismo nivel pueden ser sintetizados para obtener un Orbe de Sueño del siguiente nivel. Si los dos Orbes de Sueño comparten el mismo nombre, producirán el mismo Orbe de Sueño de un nivel superior. Si los dos Orbes de Sueño son diferentes, producirán un Orbe de Sueño aleatorio de un nivel superior.",
  str_season_maze_s2_help_disc_705 = "Después de que cada desafío de Echoes of a Dream termine, se pueden conservar las 5 Dream Orbs de nivel más alto equipadas para el próximo desafío. Cuando se equipan menos de cinco Dream Orbs, se conservarán las Dream Orbs de nivel más alto en tu mochila. Las Dream Orbs retenidas se restablecerán a Lv. 1.",
  str_season_maze_s2_guide_warn_90020101 = "Aviso: Has llegado con éxito al espacio entrelazado de los sueños. Por favor, sigue la guía de Enlightener y vence al Devorador de Sueños Definitivo.",
  str_season_maze_s2_guide_warn_90020102 = "Aviso: Toque aquí para comenzar su exploración.",
  str_season_maze_s2_guide_warn_90020201 = "Aviso: Después de cada exploración, recibirás Puntos de Sueño de acuerdo a tu calificación. Acumula Puntos de Sueño y alcanza ciertos niveles para obtener sus correspondientes recompensas de exploración.",
  str_season_maze_s2_guide_warn_90020202 = "Aviso: Derrota a los Devoradores de Sueños y completa las Misiones de Sueño para obtener Puntos de Sueño.",
  str_season_maze_s2_guide_warn_90020203 = "Aviso: Los niveles de recompensa se desbloquearán con el tiempo. Después de reclamar todas las recompensas del nivel actual, podrás ver la cuenta regresiva hasta que se desbloquee el próximo nivel.",
  str_season_maze_s2_guide_warn_90020301 = "Aviso: Los sueños están estructurados en varios niveles. Los niveles más altos significan desafíos más difíciles y más puntos al completarlos. El nivel actual debe completarse para desafiar al siguiente. Ciertos niveles se desbloquearán automáticamente después de que haya transcurrido cierto tiempo.",
  str_season_maze_s2_guide_warn_90020302 = "Análisis en progreso... Se ha detectado un Devorador de Sueños Definitivo, y está causando estragos dentro de este sueño. Toca el Devorador de Sueños Definitivo para ver más información detallada sobre él.",
  str_season_maze_s2_guide_warn_90020303 = "Sugerencia: Basado en el elemento del Devorador de Sueños Definitivo, Enlightener sugiere la siguiente alineación para esta exploración.",
  str_season_maze_s2_guide_circle_90020401 = "Explicación: Los sueños están compuestos de varios Reinos de Sueños, cada uno de los cuales desencadena diferentes eventos.",
  str_season_maze_s2_guide_warn_90020402 = "Explicación: Usa la Tarjeta de Adivinación de Sueños de Enlightener para atravesar los Reinos de Sueños. El contador de \"Paso de Acción\" en la parte superior izquierda muestra el número de pasos dados; los efectos especiales activados por el movimiento se muestran en la esquina inferior derecha de la pantalla.",
  str_season_maze_s2_guide_warn_90020403 = "Explicación: Seleccione una Carta de Adivinación de Sueños y luego toque Jugar para ejecutar todos sus efectos; lo mismo se puede hacer arrastrando una Carta de Adivinación de Sueños al centro de la pantalla.",
  str_season_maze_s2_guide_warn_90020404 = "Aviso: Puedes ver todos los Recursos de Sueño adquiridos durante la exploración actual aquí. Esto incluye Oro, Interés, Rondas, Niveles, Experiencia y más.",
  str_season_maze_s2_guide_warn_90020501 = "Aviso: Gana EXP de Sueño para aumentar el Nivel de Sueño. Al hacerlo, aumenta los niveles de Aurorian y de equipo y otorga otras recompensas de recursos.",
  str_season_maze_s2_guide_warn_90020502 = "Advertencia: Para continuar explorando, debes mantener un número suficiente de rondas. Si tus rondas llegan a 0, la exploración terminará automáticamente.",
  str_season_maze_s2_guide_warn_90020503 = "Explicación: En Sueños, el Oro se puede usar para intercambiar por objetos poderosos. Al final de cada ronda, la cantidad de Oro que puedes obtener es igual a la cantidad de Interés ganado.",
  str_season_maze_s2_guide_warn_90020504 = "Aviso: En la Bolsa de Herramientas, puedes verificar los Aurorians, Equipo de Sueño y Cartas de Adivinación de Sueños que se han agregado a la alineación actual. La Bolsa de Herramientas se vaciará al final de cada exploración.",
  str_season_maze_s2_guide_warn_90020505 = "Advertencia: El Devorador de Sueños atacará después de que hagas un cierto número de movimientos. Derrota al último Devorador de Sueños Definitivo para terminar esta exploración.",
  str_season_maze_s2_guide_warn_90020601 = "Consejo: Aquí, puedes ver las condiciones del campo de batalla y la información del enemigo de esta batalla para ajustar tus tácticas en consecuencia. Como tu Enlightener, creo que puedes idear la estrategia perfecta para el combate.",
  str_season_maze_s2_guide_warn_90020602 = "Consejo: La victoria contra el Devorador de Sueños produce recompensas abundantes.",
  str_season_maze_s2_guide_warn_90020603 = "Con Anticipación: Vamos a derrotar al Devorador de Sueños juntos.",
  str_season_maze_s2_guide_warn_90020701 = "Cada vez que ingreses a un Reino de Sueño Seguro, puedes invocar a un nuevo Aurorian para agregar a tu alineación.",
  str_season_maze_s2_guide_warn_90020702 = "En la interfaz de compra, puedes intercambiar Monedas de Sueño por Equipo de Sueño y Artículos de Ayuda de Sueño.",
  str_season_maze_s2_guide_warn_90020703 = "Después de almacenar una cantidad designada de Monedas de Sueño en la Forja de Sueños, puedes desbloquear elementos de Sueño aún más poderosos y otros efectos especiales.",
  str_season_maze_s2_guide_warn_90020704 = "La Caja de Medicina puede usarse para curar a los Aurorianos en tu alineación actual a expensas de las Monedas de Sueño. ¡Recuerda mantener a tu equipo saludable!",
  str_season_maze_s2_guide_warn_90020705 = "Si algún Auroriano queda incapacitado en la batalla, puede ser revivido en la Sala de Operaciones a costa de Monedas de Sueño.",
  str_season_maze_s2_guide_warn_90020706 = "Después de descansar, toca el botón \"Iniciar Siguiente Ronda\" para continuar el desafío.",
  str_season_maze_s2_guide_warn_90020801 = "Los Aurorians pueden ser enviados para completar misiones en Reinos de Sueños Inexplorados. Los Aurorians enviados regresarán después de un número determinado de rondas, junto con las Recompensas de Despacho por sus misiones. Los Aurorians que cumplan con los Requisitos de Despacho de sus misiones ganarán recompensas adicionales.",
  str_season_maze_s2_guide_warn_90020802 = "Toca aquí para seleccionar un Aurorian para el envío. Los Aurorians enviados no se pueden agregar a la alineación hasta que regresen.",
  str_season_maze_s2_guide_warn_90020901 = "En el Reino del Sueño de Comercio, el Navegante puede intercambiar Orbes de Sueño con aliados que actualmente están en otros Sueños, aumentando así sus efectos.",
  str_season_maze_s2_guide_warn_90020902 = "Cada instancia de un Comercio en los Reinos de Sueños proporciona al Navegante 6 oportunidades de comercio para los Orbes de Sueños, y cada aliado solo puede ser intercambiado una vez.",
  str_season_maze_s2_guide_warn_90020903 = "Toca un Orbe de Sueño para iniciar un intercambio. Los Orbes de Sueño recién obtenidos heredarán la calificación de los originales.",
  str_season_maze_s2_guide_warn_90021001 = "En los Reinos de Sueños de la Adivinación, el Navegante puede gastar Monedas de Sueño para reiniciar o eliminar las Cartas de Adivinación de Sueños que posee actualmente.",
  str_season_maze_s2_guide_warn_90021002 = "Las actuales Cartas de Adivinación de Sueños del Navegador se muestran a continuación. Toca y arrastra una carta para restablecerla o eliminarla.",
  str_season_maze_s2_guide_warn_90021003 = "Arrastra una Tarjeta de Adivinación de Sueños a esta ubicación y gasta la cantidad requerida de Oro para eliminarla. El costo en Oro aumenta con cada eliminación de tarjeta.",
  str_season_maze_s2_guide_warn_90021004 = "Arrastra una Carta de Adivinación de Sueños a esta ubicación y gasta la cantidad requerida de Oro para reiniciarla, lo que elimina la carta actual y produce una nueva. El costo en Oro aumenta con cada reinicio de carta.",
  str_season_maze_s2_mail_gm_season = "Ecos de un Sueño",
  str_season_maze_s2_mail_title_season = "Recompensas no reclamadas",
  str_season_maze_s2_mail_detail_season = "¡El evento de los Ecos de un Sueño ha terminado! ¡Aquí están las recompensas que no lograste reclamar durante el evento!"
}
return config
